async function seed() {
  const pool = new Pool({ connectionString: dbUrl });
  try {
    console.log('Creating table...');
    await pool.query('DROP TABLE IF EXISTS temp');
    await pool.query(`
      CREATE TABLE temp (
        id SERIAL PRIMARY KEY,
        sno INTEGER,
        application_no TEXT,
        permanent_id TEXT,
        institute_name TEXT
      )
    `);
    console.log('Table created. Inserting data...');

    const BATCH = 100;
    let inserted = 0;
    for (let i = 0; i < data.length; i += BATCH) {
      const batch = data.slice(i, i + BATCH);
      const placeholders = batch.map((_, idx) =>
        `($${idx*4+1}, $${idx*4+2}, $${idx*4+3}, $${idx*4+4})`
      ).join(',');
      const flatValues = batch.flatMap(r => [r[0], r[1], r[2] || null, r[3]]);
      await pool.query(
        `INSERT INTO temp (sno, application_no, permanent_id, institute_name) VALUES ${placeholders}`,
        flatValues
      );
      inserted += batch.length;
      if (inserted % 500 === 0) console.log(`Inserted ${inserted}...`);
    }

    const res = await pool.query('SELECT COUNT(*) FROM temp');
    console.log(`Done. Total rows in table: ${res.rows[0].count}`);
  } finally {
    await pool.end();
  }
}

seed().catch(e => { console.error(e); process.exit(1); });
